practice.solution:
def harmony(hue, kind):
    if kind == "complementary":
        offs = [0, 180]
    elif kind == "analogous":
        offs = [-30, 0, 30]
    elif kind == "triadic":
        offs = [0, 120, 240]
    else:
        offs = [0, 150, 210]
    return [(hue + o) % 360 for o in offs]

