    pass

practice.solution:
def contrast(a, b):
    def lum(c):
        vals = []
        for v in c:
            x = v / 255.0
            if x <= 0.03928:
                vals.append(x / 12.92)
            else:
                vals.append(((x + 0.055) / 1.055) ** 2.4)
        return 0.2126 * vals[0] + 0.7152 * vals[1] + 0.0722 * vals[2]
    la = lum(a)
    lb = lum(b)
    if la < lb:
        la, lb = lb, la
    return round((la + 0.05) / (lb + 0.05), 2)

