def rhythm(sizes):
    # your code
    pass

practice.solution:
def rhythm(sizes):
    same = True
    up = True
    down = True
    for i in range(1, len(sizes)):
        if sizes[i] != sizes[i - 1]:
            same = False
        if sizes[i] <= sizes[i - 1]:
            up = False
        if sizes[i] >= sizes[i - 1]:
            down = False
    if same:
        return "regular"
    if up or down:
        return "progressive"
    return "varied"

