practice.solution:
def nearest_third(w, h, x, y):
    pts = [[w / 3.0, h / 3.0], [2 * w / 3.0, h / 3.0], [w / 3.0, 2 * h / 3.0], [2 * w / 3.0, 2 * h / 3.0]]
    best = 0
    bestd = (pts[0][0] - x) ** 2 + (pts[0][1] - y) ** 2
    for i in range(1, 4):
        d = (pts[i][0] - x) ** 2 + (pts[i][1] - y) ** 2
        if d < bestd:
            bestd = d
            best = i
    return best

